#include "ClaraCyberModel.h"
#include <algorithm>
#include <cctype>
#include <iomanip>
#include <sstream>
namespace ClaraCyber{
namespace{const int numbers[]={21,22,23,443,8080};const char* hosts[]={"192.168.10.50","192.168.10.30","192.168.10.99"};const char* server="192.168.20.10";int portIndex(int p){for(int i=0;i<5;i++)if(numbers[i]==p)return i;return -1;}int hostIndex(const std::string&s){for(int i=0;i<3;i++)if(s==hosts[i])return i;return -1;}std::string lower(std::string s){for(char&c:s)c=char(std::tolower((unsigned char)c));return s;}bool all(const std::array<bool,3>&v){return v[0]&&v[1]&&v[2];}}
Model::Model():rules{{1,true,"*","*"},{2,true,hosts[0],server},{3,false,"*",server}}{}
std::array<std::pair<std::string,std::string>,5> Model::credentials(){return {{{"admin","password"},{"root","root"},{"test","test"},{"admin","1234"},{"admin","admin"}}};}
void Model::award(int n){if(day<1||day>3||!path[day-1]||n<0||n>4)return;unsigned bit=1u<<n;if(rewards[day-1]&bit)return;rewards[day-1]|=bit;int&v=path[day-1]=='A'?red:blue;v=std::min(100,v+5);}
bool Model::choose(char p){if(day>3||(p!='A'&&p!='B')||path[day-1]||finished[day-1])return false;if(day==1&&inspected.size()<3)return false;if(day==2&&!notes.count("N2.1"))return false;if(day==3&&(!notes.count("N3.1")||!notes.count("N3.2")))return false;path[day-1]=p;award(0);return true;}
bool Model::inspectPort(int p){if(day>3||finished[day-1])return false;if(day!=1||portIndex(p)<0)return false;inspected.insert(p);if(inspected.size()>=3){notes.insert("N1.1");notes.insert("N1.2");}return true;}
bool Model::learn(int n){if(day>3||finished[day-1])return false;if(day==2&&n==1){notes.insert("N2.1");return true;}if(day==3&&(n==1||n==2)){notes.insert(n==1?"N3.1":"N3.2");return true;}return false;}
bool Model::recognizeLog(){if(day>3||finished[day-1])return false;if(day>3||path[day-1]!='B')return false;logRecognized=true;notes.insert(day==1?"N1.3":day==2?"N2.3":"N3.3");award(1);return true;}
bool Model::classify(int p,int c){if(day>3||finished[day-1])return false;int i=portIndex(p);if(day!=1||path[0]!='A'||!scanned||i<0||c<1||c>3)return false;classification[i]=c;refresh();return true;}
bool Model::check22(){if(day>3||finished[day-1])return false;if(day!=1||path[0]!='A'||!scanned||classification!=std::array<int,5>{{2,3,2,1,2}})return false;seen22=true;award(3);return true;}
bool Model::setPort(int p,bool on){if(day>3||finished[day-1])return false;int i=portIndex(p);if(day!=1||path[0]!='B'||!logRecognized||i<0||(!on&&p==8080&&!inspected.count(8080)))return false;ports[i]=on;scanned=false;materials=false;refresh();return true;}
bool Model::openMaterials(){if(day>3||finished[day-1])return false;if(day!=1||path[0]!='B')return false;materials=ports[3];refresh();return materials;}
bool Model::expect(int i,bool pass){if(day>3||finished[day-1])return false;if(day!=2||path[1]!='A'||i<0||i>2)return false;expected[i]=pass;refresh();return true;}
Decision Model::evaluate(const std::string&from,const std::string&to)const{for(const Rule&r:rules)if((r.from=="*"||r.from==from)&&(r.to=="*"||r.to==to))return{r.allow,r.id};return{false,0};}
Flow Model::flow(const std::string&from,const std::string&to)const{Decision request=evaluate(from,to);return {request,request.allowed};}
bool Model::reorder(const std::vector<int>&ids){if(day>3||finished[day-1])return false;if(day!=2||path[1]!='B'||!logRecognized||ids.size()<2||ids.size()>3)return false;std::vector<Rule> next;std::set<int> used;for(int id:ids){if(id<1||id>3||!used.insert(id).second)return false;if(id==1)next.push_back({1,true,"*","*"});if(id==2)next.push_back({2,true,hosts[0],server});if(id==3)next.push_back({3,false,"*",server});}if(!used.count(2)||!used.count(3))return false;rules=next;verified={{false,false,false}};refresh();return true;}
std::string Model::command(const std::string&line){std::istringstream in(line);std::vector<std::string>a;std::string t;while(in>>t)a.push_back(t);if(a.empty())return "";if(a[0]=="spiega"){if(a.size()!=2)return "Uso: spiega comando";if(a[1]=="nmap")return "Prova le porte del dispositivo autorizzato.";if(a[1]=="ping")return "Verifica se un dispositivo risponde.";if(a[1]=="curl")return "Legge le intestazioni HTTP.";if(a[1]=="openssl")return "Verifica una connessione TLS.";if(a[1]=="ssh")return "Richiede accesso remoto cifrato.";return "Comando sconosciuto.";}if(day>3||finished[day-1]||!path[day-1])return "Giornata non attiva: scegli un percorso o passa al giorno successivo.";if(a[0]=="nmap"){if(a.size()!=2)return "Manca il destinatario.";if(day!=1)return "Comando non disponibile in questo scenario.";if(a[1]!="192.168.10.20")return a[1]=="192.168.10.200"?"Host seems down.":"Destinatario fuori autorizzazione.";scanned=true;if(path[0]=='A'){notes.insert("N1.3");award(1);}refresh();std::string out="SIMULAZIONE LOCALE\n";for(int i=0;i<5;i++)out+=std::to_string(numbers[i])+(ports[i]?" open\n":" closed\n");return out+"La scansione ha verificato le porte simulate.";}if(a[0]=="ping"&&day==1){if(a.size()!=2)return "Uso: ping indirizzo";if(a[1]!="192.168.10.20")return "Destinatario fuori autorizzazione.";return "SIMULAZIONE LOCALE: risposta dal server didattico.";}if(a[0]=="ssh"){if(day!=1||a.size()!=2)return "Uso: ssh utente@indirizzo";auto at=a[1].find('@');if(at==std::string::npos||at==0)return "Specifica utente e destinatario.";if(a[1].substr(at+1)!="192.168.10.20")return "Destinatario fuori autorizzazione.";return ports[1]?"SIMULAZIONE LOCALE: porta 22 raggiungibile; nessuna autenticazione reale.":"SIMULAZIONE LOCALE: connessione rifiutata.";}if(a[0]=="ping"){if(day!=2)return "Comando non disponibile in questo scenario.";if(a.size()!=4||a[1]!="-I")return "Uso: ping -I partenza destinazione";int i=hostIndex(a[2]);if(i<0)return "Postazione fuori autorizzazione.";if(a[3]!=server)return a[3]=="192.168.20.99"?"Nessun dispositivo risponde.":"Destinatario fuori autorizzazione.";if(path[1]=='A'&&expected[i]<0)return "Indica prima il risultato atteso.";Flow test=flow(a[2],a[3]);Decision d=test.request;bool complete=d.allowed&&test.reply;observed[i]=complete?1:0;if(path[1]=='B'&&logRecognized)verified[i]=complete==(i==0);refresh();return std::string("SIMULAZIONE LOCALE: ")+(complete?"Connessione riuscita, risposta associata consentita":"Connessione bloccata, nessuna risposta")+"; regola "+std::to_string(d.rule)+". La prova segue la prima regola corrispondente.";}if(a[0]=="curl"){if(day!=3||a.size()!=3||a[1]!="-I")return "Uso: curl -I http://192.168.20.10/pannello";if(a[2]!="http://192.168.20.10/pannello"&&a[2]!="https://192.168.20.10/pannello")return "Destinatario fuori autorizzazione.";if(a[2][4]=='s'&&!tls)return "Connessione TLS non disponibile.";return "SIMULAZIONE LOCALE\nHTTP/1.1 200 OK\nContent-Type: text/html\n\nSolo intestazioni; nessun corpo o credenziale.";}if(a[0]=="openssl"){if(day!=3||a.size()!=4||a[1]!="s_client"||a[2]!="-connect")return "Uso: openssl s_client -connect indirizzo:porta";if(a[3]!="192.168.20.10:443")return "Destinatario fuori autorizzazione.";return tls?"SIMULAZIONE LOCALE: TLS attivo, certificato didattico.":"SIMULAZIONE LOCALE: connessione TLS non disponibile.";}return "command not found: "+a[0];}
bool Model::identifyRule(int id){if(day>3||finished[day-1])return false;if(day!=2||path[1]!='A'||observed[0]<0||observed[1]<0||observed[2]<0||id!=1||evaluate(hosts[1],server).rule!=1)return false;notes.insert("N2.3");award(3);return true;}
bool Model::login(const std::string&u,const std::string&p){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='A')return false;bool ok=adminEnabled&&!passwordChanged&&u=="admin"&&p=="admin";if(log.size()>=1000)log.erase(log.begin());log.push_back(std::string("Tentativo simulato: ")+(u=="admin"?"admin":"altro utente")+(ok?" riuscito":" fallito"));if(ok){notes.insert("N3.3");award(1);}return ok;}
bool Model::networkVision(bool encrypted){if(day>3||finished[day-1])return false;if(day!=3||!path[2])return false;if(path[2]=='A'){if(!(rewards[2]&2))return false;if(encrypted)tlsSeen=true;else plainSeen=true;refresh();return true;}if(!tls||!adminEnabled)return false;trafficChecked=true;refresh();return true;}
PasswordCheck Model::passwordCheck(const std::string&p){std::string l=lower(p);size_t count=0;std::set<unsigned char> distinct;for(unsigned char c:p){if((c&0xc0)!=0x80)++count;distinct.insert(c);}bool common=distinct.size()<6;for(const char* bad:{"password","123456","qwerty","letmein","benvenuto","welcome","abcdef","000000","111111"})if(l.find(bad)!=std::string::npos)common=true;return {count>=12,!common,l!="admin",l.find("admin")==std::string::npos};}
bool Model::changePassword(const std::string&p){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='B'||!logRecognized||!passwordCheck(p).valid())return false;passwordChanged=true;oldRejected=teamAccepted=false;refresh();return true;}
bool Model::setTls(bool v){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='B'||!logRecognized)return false;tls=v;trafficChecked=false;refresh();return true;}
bool Model::setAdmin(bool v){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='B'||!logRecognized)return false;adminEnabled=v;teamAccepted=false;refresh();return true;}
bool Model::verifyOld(){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='B'||!passwordChanged)return false;oldRejected=true;refresh();return true;}
bool Model::verifyTeam(){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='B'||!passwordChanged||!adminEnabled)return false;teamAccepted=true;refresh();return true;}
bool Model::recognizeWeaknesses(bool password,bool encryption){if(day>3||finished[day-1])return false;if(day!=3||path[2]!='A'||!plainSeen||!tlsSeen||!password||!encryption)return false;weaknesses=true;award(3);return true;}
void Model::refresh(){if(day==1&&path[0]=='A'&&classification==std::array<int,5>{{2,3,2,1,2}})award(2);if(day==1&&path[0]=='B'&&ports==std::array<bool,5>{{false,true,false,true,false}}){award(2);if(scanned&&materials)award(3);}if(day==2&&path[1]=='A'){if(observed[0]>=0||observed[1]>=0||observed[2]>=0)award(1);if(expected==std::array<int,3>{{1,0,0}}&&observed==std::array<int,3>{{1,1,1}}){notes.insert("N2.2");award(2);}}if(day==2&&path[1]=='B'&&evaluate(hosts[0],server).allowed&&!evaluate(hosts[1],server).allowed&&!evaluate(hosts[2],server).allowed){award(2);if(all(verified)){notes.insert("N2.2");award(3);}}if(day==3&&path[2]=='A'&&plainSeen&&tlsSeen)award(2);if(day==3&&path[2]=='B'&&passwordChanged&&tls&&adminEnabled){notes.insert("N3.4");award(2);if(oldRejected&&teamAccepted&&trafficChecked)award(3);}}
bool Model::report(){if(day>3||finished[day-1]||(rewards[day-1]&15)!=15)return false;if(day==1&&path[0]=='A'&&(classification!=std::array<int,5>{{2,3,2,1,2}}||!seen22))return false;if(day==1&&path[0]=='B'&&(ports!=std::array<bool,5>{{false,true,false,true,false}}||!scanned||!materials))return false;if(day==2&&path[1]=='B'&&(!evaluate(hosts[0],server).allowed||evaluate(hosts[1],server).allowed||evaluate(hosts[2],server).allowed||!all(verified)))return false;if(day==3&&path[2]=='B'&&(!passwordChanged||!tls||!adminEnabled||!oldRejected||!teamAccepted||!trafficChecked))return false;award(4);finished[day-1]=true;notes.insert(day==1?"N1.4":day==2?"N2.4":"N3.5");if(day==3&&path[2]=='A')notes.insert("N3.4");return true;}
bool Model::opposite(){if(day>3||!finished[day-1]||perspective[day-1])return false;perspective[day-1]=true;int&v=path[day-1]=='A'?blue:red;v=std::min(100,v+3);return true;}
bool Model::next(){if(day>3||!finished[day-1])return false;day++;scanned=materials=seen22=logRecognized=plainSeen=tlsSeen=weaknesses=false;hints=0;return true;}
std::string Model::hint(){if(day>3)return "Gli incarichi sono conclusi.";int step=0;unsigned r=rewards[day-1];if(path[day-1]){step=1;while(step<=4&&(r&(1u<<step)))++step;}int key=day*20+(path[day-1]=='A'?5:path[day-1]=='B'?10:0)+step;if(key!=hintStage){hints=0;hintStage=key;}hints=std::min(3,hints+1);const char* const* options=nullptr;static const char* d1intro[]={"Guarda cosa mostra la lente sul server.","Tocca le porte con la luce verde.","Esamina almeno tre delle cinque porte accese."};static const char* d1red[]={"Partiamo dall'indirizzo: c'e uno strumento che prova le porte?","Nella guida cerca la voce sulle porte.","Scrivi nmap seguito dall'indirizzo del server."};static const char* d1blue[]={"Guarda quante porte tocca lo stesso indirizzo in pochi secondi.","Confronta le righe evidenziate con quelle di Luca.","Nel registro confronta le righe da 192.168.10.77."};static const char* d2[]={"Guarda quale regola ha fatto passare il traffico.","Confronta la prima regola con quella che blocca il server.","Il firewall si ferma alla prima regola corrispondente."};static const char* d3red[]={"Nel taccuino trovi una lista di credenziali.","Il pannello usa l'utente admin.","Prova una delle coppie admin e confronta i pacchetti."};static const char* d3blue[]={"Guarda l'esito dell'ultimo accesso.","Nell'amministrazione account cerca la password predefinita.","Cambia password e attiva la cifratura, mantenendo l'account."};if(day==1)options=!path[0]?d1intro:path[0]=='A'?d1red:d1blue;else if(day==2)options=d2;else options=path[2]=='A'?d3red:d3blue;return options[hints-1];}
std::string Model::save()const{std::ostringstream o;o<<"CLARACYBER4 "<<day<<' '<<red<<' '<<blue<<' ';for(auto x:path)o<<int(x)<<' ';for(auto x:rewards)o<<x<<' ';for(auto x:perspective)o<<x<<' ';for(auto x:finished)o<<x<<' ';for(auto x:ports)o<<x<<' ';for(auto x:classification)o<<x<<' ';for(auto x:expected)o<<x<<' ';for(auto x:observed)o<<x<<' ';for(auto x:verified)o<<x<<' ';o<<scanned<<' '<<materials<<' '<<seen22<<' '<<logRecognized<<' '<<plainSeen<<' '<<tlsSeen<<' '<<passwordChanged<<' '<<tls<<' '<<adminEnabled<<' '<<oldRejected<<' '<<teamAccepted<<' '<<trafficChecked<<' '<<weaknesses<<' '<<hints<<' ';o<<inspected.size()<<' ';for(auto x:inspected)o<<x<<' ';o<<notes.size()<<' ';for(auto&x:notes)o<<std::quoted(x)<<' ';o<<rules.size()<<' ';for(auto&r:rules)o<<r.id<<' ';o<<log.size()<<' ';for(auto&x:log)o<<std::quoted(x)<<' ';o<<dialogueScene<<' '<<dialogueOffset<<' ';for(auto x:sceneSeen)o<<x<<' ';o<<hintStage<<' ';for(const auto&x:expectations)o<<std::quoted(x)<<' ';return o.str();}
bool Model::load(const std::string&s){if(s.size()>65536)return false;std::istringstream i(s);Model n;std::string magic;int c;size_t count;if(!(i>>magic>>n.day>>n.red>>n.blue)||(magic!="CLARACYBER1"&&magic!="CLARACYBER2"&&magic!="CLARACYBER3"&&magic!="CLARACYBER4")||n.day<1||n.day>4||n.red<0||n.red>100||n.blue<0||n.blue>100)return false;for(auto&x:n.path){if(!(i>>c)||(c!=0&&c!='A'&&c!='B'))return false;x=char(c);}for(auto&x:n.rewards)if(!(i>>x)||x>31)return false;auto readBool=[&](bool&x){int v;if(!(i>>v)||v<0||v>1)return false;x=v;return true;};for(auto&x:n.perspective)if(!readBool(x))return false;for(auto&x:n.finished)if(!readBool(x))return false;for(auto&x:n.ports)if(!readBool(x))return false;for(auto&x:n.classification)if(!(i>>x)||x<0||x>3)return false;for(auto&x:n.expected)if(!(i>>x)||x< -1||x>1)return false;for(auto&x:n.observed)if(!(i>>x)||x< -1||x>1)return false;for(auto&x:n.verified)if(!readBool(x))return false;bool* flags[]={&n.scanned,&n.materials,&n.seen22,&n.logRecognized,&n.plainSeen,&n.tlsSeen,&n.passwordChanged,&n.tls,&n.adminEnabled,&n.oldRejected,&n.teamAccepted,&n.trafficChecked,&n.weaknesses};for(auto p:flags)if(!readBool(*p))return false;if(!(i>>n.hints)||n.hints<0||n.hints>3)return false;if(!(i>>count)||count>5)return false;n.inspected.clear();while(count--){if(!(i>>c)||portIndex(c)<0||!n.inspected.insert(c).second)return false;}if(!(i>>count)||count>13)return false;n.notes.clear();while(count--){std::string x;if(!(i>>std::quoted(x))||x.size()!=4||x[0]!='N'||x[1]<'1'||x[1]>'3'||x[2]!='.'||x[3]<'1'||x[3]>(x[1]=='3'?'5':'4')||!n.notes.insert(x).second)return false;}if(!(i>>count)||count<2||count>3)return false;n.rules.clear();std::set<int> ids;while(count--){if(!(i>>c)||c<1||c>3||!ids.insert(c).second)return false;if(c==1)n.rules.push_back({1,true,"*","*"});if(c==2)n.rules.push_back({2,true,hosts[0],server});if(c==3)n.rules.push_back({3,false,"*",server});}if(!ids.count(2)||!ids.count(3))return false;if(!(i>>count)||count>1000)return false;n.log.clear();while(count--){std::string x;if(!(i>>std::quoted(x))||x.size()>200)return false;n.log.push_back(x);}if(magic=="CLARACYBER2"||magic=="CLARACYBER3"||magic=="CLARACYBER4"){if(!(i>>n.dialogueScene>>n.dialogueOffset)||n.dialogueScene< -1||n.dialogueScene>63||n.dialogueOffset<0||n.dialogueOffset>200)return false;for(auto&x:n.sceneSeen)if(!(i>>x))return false;if((magic=="CLARACYBER3"||magic=="CLARACYBER4")&&(!(i>>n.hintStage)||n.hintStage< -1||n.hintStage>100))return false;if(magic=="CLARACYBER4")for(auto&x:n.expectations)if(!(i>>std::quoted(x))||x.size()>500)return false;}i>>std::ws;if(!i.eof())return false;for(int k=0;k<3;k++){if(!n.path[k]&&(n.rewards[k]||n.finished[k]||n.perspective[k]))return false;if(n.finished[k]&&n.rewards[k]!=31)return false;if(n.perspective[k]&&!n.finished[k])return false;if(k<n.day-1&&!n.finished[k])return false;}*this=n;return true;}
}
